\documentclass[11pt]{amsart}

\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}{Definition}
\newtheorem{example}{Example}
\theoremstyle{remark}
\newtheorem*{remark}{Remark}

\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\K}{K}
\newcommand{\PP}{\mathbb{P}}
\newcommand{\hpq}{h^{p,q}}
\newcommand{\Epoly}{E}
\newcommand{\eulerchar}{\chi}
\DeclareMathOperator{\mirror}{mirror}

\title{Functional Equations of the Hodge--Deligne $E$-Polynomial:\\
Mirror Symmetry and Serre Duality as Index Reflections}
\author{Aristotle}
\date{June 18, 2026}

\begin{document}

\begin{abstract}
We study an abstract combinatorial model of a Hodge diamond---a complex dimension
$n\in\N$ together with a table of Hodge numbers $\hpq\in\Z$---and the two-variable
\emph{Hodge--Deligne $E$-polynomial}
$\Epoly(X;u,v)=\sum_{p,q}(-1)^{p+q}\hpq u^p v^q$ attached to it, evaluated over an
arbitrary field $\K$. We prove two functional equations. First, an unconditional
\emph{mirror} equation
$\Epoly(\mirror X;u,v)=(-1)^n u^n\,\Epoly(X;u^{-1},v)$, where $\mirror$ is the
reflection $(p,q)\mapsto(n-p,q)$. Second, a \emph{Serre/Poincar\'e} equation
$\Epoly(X;u,v)=(uv)^n\,\Epoly(X;u^{-1},v^{-1})$ valid whenever $X$ satisfies Serre
duality $\hpq=h^{n-p,n-q}$. Specialising at $u=v=1$ recovers the Euler characteristic
$\eulerchar(X)=\sum(-1)^{p+q}\hpq$, and the mirror equation degenerates to the numerical
identity $\eulerchar(\mirror X)=(-1)^n\eulerchar(X)$. All proofs rest on a single
combinatorial principle: reflection of a summation index $p\mapsto n-p$, together with
the parity bookkeeping $(-1)^{(n-p)+q}=(-1)^n(-1)^{p+q}$ and the exponent bookkeeping
$u^{n-p}=u^n(u^{-1})^p$. The results are formalised over an arbitrary field.
\end{abstract}

\maketitle

\section{Introduction}

The Hodge diamond of a smooth compact K\"ahler manifold $X$ of complex dimension $n$
records the dimensions $\hpq=\dim H^q(X,\Omega^p_X)$ of its Dolbeault cohomology. These
numbers satisfy two fundamental symmetries: \emph{Serre duality}
$\hpq=h^{n-p,n-q}$ (a half-turn of the diamond), and \emph{mirror symmetry}
(conjecturally, for Calabi--Yau manifolds), which exchanges a manifold with a
topologically distinct partner whose diamond is reflected.

A standard way to package the diamond is the Hodge--Deligne $E$-polynomial, a
two-variable generating function whose specialisations recover the Euler
characteristic, the Poincar\'e polynomial, and (over finite fields) point counts. We
isolate, in a deliberately minimal abstract setting, the precise sense in which both
symmetries are \emph{functional equations} of the $E$-polynomial, and show that both---
together with the classical numerical fact $\eulerchar(\mirror)=(-1)^n\eulerchar$---
follow from one move: reflecting a summation index. Everything is proved over an
arbitrary field $\K$, so the results apply uniformly to the topological
($\K=\mathbb{C}$), real, rational, and finite-field incarnations of the invariant.

\section{Definitions}

Throughout, $\K$ is a field and $\mathrm{range}(n+1)=\{0,1,\dots,n\}$. Subtraction
$n-p$ is truncated natural-number subtraction (so $n-p=0$ when $p>n$).

\begin{definition}[Hodge diamond]
A \emph{Hodge diamond} is a pair $X=(n,h)$ consisting of a complex dimension $n\in\N$
and a function $h:\N\times\N\to\Z$, written $\hpq$. Only the values with $p,q\le n$ are
mathematically meaningful; the remaining values are treated as padding and never enter
any sum below.
\end{definition}

\begin{definition}[Hodge--Deligne $E$-polynomial]
For a field $\K$ and $u,v\in\K$,
\[
\Epoly(X;u,v):=\sum_{p=0}^{n}\sum_{q=0}^{n}(-1)^{p+q}\,(\hpq:\K)\,u^p v^q.
\]
\end{definition}

\begin{definition}[Mirror]
The \emph{mirror} of $X=(n,h)$ is $\mirror X:=(n,h')$ with $h'^{p,q}:=h^{n-p,\,q}$.
Thus $(\mirror X).n=X.n$ and $(\mirror X).h\,p\,q=X.h\,(n-p)\,q$.
\end{definition}

\begin{definition}[Serre duality]
$X$ is \emph{Serre self-dual}, written $\mathrm{SerreDual}\,X$, if $\hpq=h^{n-p,\,n-q}$
for all $p,q\le n$.
\end{definition}

\begin{definition}[Euler characteristic and total dimension]
\[
\eulerchar(X):=\sum_{p=0}^{n}\sum_{q=0}^{n}(-1)^{p+q}\hpq\in\Z,
\qquad
b(X):=\sum_{p=0}^{n}\sum_{q=0}^{n}\hpq\in\Z.
\]
\end{definition}

\begin{remark}
Because $h$ is defined on all of $\N\times\N$, the mirror map is an involution only on
the support $p\le n$ (outside it, $n-p=0$ collapses information). Involutivity is
therefore stated on the support and at the level of $\Epoly$, rather than as a
definitional equality of structures. The formalisation also records that the total
dimension is mirror-invariant and packages the involution as Calabi--Yau data.
\end{remark}

\section{Main results}

\subsection{Specialisation to the Euler characteristic}

\begin{theorem}[\texttt{epoly\_one\_one\_eq\_eulerChar}]\label{thm:spec}
For any field $\K$, \(\Epoly(X;1,1)=(\eulerchar(X):\K).\)
\end{theorem}

\begin{proof}[Proof sketch]
Substituting $u=v=1$ makes every monomial $u^p v^q=1$, so each summand becomes
$(-1)^{p+q}(\hpq:\K)$. The double sum is then the image under the ring homomorphism
$\Z\to\K$ of the integer double sum defining $\eulerchar(X)$; the cast commutes with
$+$ and $\cdot$, hence passes through the finite sums.
\end{proof}

This is the specialisation bridge converting polynomial identities into numerical ones.

\subsection{The mirror functional equation}

\begin{theorem}[\texttt{epoly\_mirror\_functional\_equation}]\label{thm:mirror}
For $u\ne 0$ and any $v$,
\[
\Epoly(\mirror X;u,v)=(-1)^n\,u^n\,\Epoly(X;u^{-1},v).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Expand the left-hand side using the mirror definition:
$\Epoly(\mirror X;u,v)=\sum_{p,q}(-1)^{p+q}(h^{n-p,q}:\K)u^p v^q$. Reflect the outer
index by the bijection $p\mapsto n-p$ on $\{0,\dots,n\}$ (injectivity from
$\mathrm{tsub\_right\_inj}$, surjectivity via $b\mapsto n-b$). After reflection the
summand carries $\hpq$ with weight $(-1)^{(n-p)+q}u^{n-p}v^q$. Apply, for $p\le n$:
\[
u^{n-p}=u^n\,(u^{-1})^p\quad(u\ne0),\qquad
(-1)^{(n-p)+q}=(-1)^n(-1)^{p+q}.
\]
Factoring out $(-1)^n u^n$ leaves
$\sum_{p,q}(-1)^{p+q}(\hpq:\K)(u^{-1})^p v^q=\Epoly(X;u^{-1},v)$.
\end{proof}

The hypothesis $u\ne0$ is necessary because the equation inverts the $u$-variable; no
symmetry of $X$ is required.

\subsection{The Serre/Poincar\'e functional equation}

\begin{theorem}[\texttt{epoly\_serre\_functional\_equation}]\label{thm:serre}
If $\mathrm{SerreDual}\,X$, then for $u\ne0$, $v\ne0$,
\[
\Epoly(X;u,v)=(uv)^n\,\Epoly(X;u^{-1},v^{-1}).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Relate $X$ to $\mirror X$ and invoke Theorem~\ref{thm:mirror}. Comparing
$\Epoly(X;u,v)$ with $\Epoly(\mirror X;u,v)$ term by term and applying the mirror
equation reflects the $u$-axis; reflecting the $v$-axis directly inside the sum (via
$q\mapsto n-q$) handles the second variable. The Serre hypothesis $\hpq=h^{n-p,n-q}$
identifies the doubly-reflected table with the original. The two sign factors combine as
$(-1)^{2n}=1$, the two exponent factors as $u^n v^n=(uv)^n$, with $v^n=v^{n-q}v^q$
handling the $v$-axis bookkeeping.
\end{proof}

This is the polynomial form of Poincar\'e duality, refined to bigraded Hodge data.

\subsection{The numerical mirror sign}

\begin{theorem}[\texttt{eulerChar\_mirror\_sign}]\label{thm:euler}
$\eulerchar(\mirror X)=(-1)^n\,\eulerchar(X).$
\end{theorem}

\begin{proof}[Proof sketch]
Two routes. (i) Specialise Theorem~\ref{thm:mirror} at $u=v=1$ (legal since $1\ne0$) and
apply Theorem~\ref{thm:spec} to both sides. (ii) Directly reflect the outer index
$p\mapsto n-p$ in the definition of $\eulerchar$; the reflected sign
$(-1)^{(n-p)+q}=(-1)^n(-1)^{p+q}$ pulls a global $(-1)^n$ out of the integer double sum.
\end{proof}

\section{The single combinatorial engine}

All four theorems are instances of one principle.

\begin{theorem}[Reflection principle]
Let $f:\{0,\dots,n\}\to A$ take values in a commutative ring $A$. Then
$\sum_{p=0}^n f(p)=\sum_{p=0}^n f(n-p)$.
\end{theorem}

Applying $p\mapsto n-p$ to a summand $(-1)^{p+q}\hpq u^p v^q$ produces three changes,
each a one-line identity valid for $p\le n$:
\begin{center}
\begin{tabular}{llll}
\hline
quantity & before & after & identity \\
\hline
Hodge weight & $\hpq$ & $h^{n-p,q}$ (or $h^{n-p,n-q}$) & mirror / Serre \\
sign & $(-1)^{p+q}$ & $(-1)^n(-1)^{p+q}$ & $\mathrm{Nat.sub\_add\_cancel}$ \\
monomial & $u^p$ & $u^n(u^{-1})^p$ & $u\ne0$, $\mathrm{pow\_add}$ \\
\hline
\end{tabular}
\end{center}
The constants $(-1)^n$, $u^n$ (and, in the two-axis case, $v^n$) pull out of the sum,
and what remains is the $E$-polynomial of the original diamond with inverted
variable(s). The Serre equation is the mirror equation in both axes; the Euler identity
is the mirror equation with the variables switched off.

\section{Worked examples}

\begin{example}[Genus-$g$ curve, $n=1$]
Nonzero entries $h^{0,0}=1,h^{1,0}=g,h^{0,1}=g,h^{1,1}=1$;
$\Epoly=1-gu-gv+uv$; $\eulerchar=2-2g$. Mirror:
$\Epoly(\mirror X)=g-u-v+guv$, and $(-1)^1u\,\Epoly(X;u^{-1},v)=g-u-v+guv$
(Theorem~\ref{thm:mirror}); $\eulerchar(\mirror)=2g-2=(-1)^1(2-2g)$
(Theorem~\ref{thm:euler}).
\end{example}

\begin{example}[Projective plane $\PP^2$, $n=2$]
$h^{0,0}=h^{1,1}=h^{2,2}=1$; $\Epoly=1+uv+u^2v^2$; $\eulerchar=3$. Serre self-dual:
$(uv)^2\Epoly(u^{-1},v^{-1})=u^2v^2+uv+1=\Epoly$ (Theorem~\ref{thm:serre}).
\end{example}

\begin{example}[K3 surface, $n=2$]
$h^{0,0}=h^{2,0}=h^{0,2}=h^{2,2}=1,h^{1,1}=20$;
$\Epoly=1+u^2+v^2+20uv+u^2v^2$; $\eulerchar=24$. Serre self-dual, so
Theorem~\ref{thm:serre} returns $\Epoly$; $n$ even, so $\eulerchar(\mirror)=24$.
\end{example}

\begin{example}[Quintic Calabi--Yau threefold, $n=3$]
$h^{0,0}=h^{3,3}=h^{3,0}=h^{0,3}=1,h^{1,1}=h^{2,2}=1,h^{2,1}=h^{1,2}=101$;
$\eulerchar=-200$. Serre self-dual; $n$ odd, so $\eulerchar(\mirror)=+200$. The mirror
quintic has $h^{1,1}=101,h^{2,1}=1$, exhibiting the Hodge-number exchange.
\end{example}

\section{Algorithms}

\textbf{$E$-polynomial assembly.} Given a diamond $\{(p,q)\mapsto\hpq\}$ and $n$, build
the coefficient table of $\Epoly$ in $O(n^2)$ monomial operations; setting $u=v=1$ and
summing yields $\eulerchar$ in $O(n^2)$.

\textbf{Functional-equation verifier.} Form the mirror/Serre-inverted polynomial
symbolically and test the relevant equation by evaluating both sides at rational sample
points with $u,v\ne0$. A polynomial identity of bidegree $\le(2n,2n)$ is certified by
agreement at $(2n+1)^2$ generic points; complexity $O(n^2\cdot\#\text{points})$.

\section{Applications and discussion}

Theorem~\ref{thm:spec} packages the Euler characteristic as a single evaluation, and
Theorem~\ref{thm:euler} then derives the mirror sign rule for free.
Theorem~\ref{thm:mirror} is the diamond-level statement of Hodge-number exchange under
mirror symmetry, a clean combinatorial consistency test. Theorem~\ref{thm:serre} is the
bigraded refinement of Poincar\'e duality. Because everything is proved over an
arbitrary field, the identities also govern $E$-polynomials counting $\mathbb{F}_q$
points, where $u,v$ specialise to Frobenius eigenvalue weights---the bridge to
arithmetic of the title.

Future directions include the Poincar\'e-polynomial specialisation $u=v$ and the
signature specialisation $u=-1$ (both immediate from the reflection engine); a full
Calabi--Yau layer making the mirror an honest involution by quotienting to the support;
and connecting the finite-field specialisation to motivic measures, where the same
functional equations become statements about zeta functions.

\end{document}

