            tot += sign * hpq(h, p, q) * (u ** p) * (v ** q)
    return tot


def grid(n: int, h: HodgeNumbers) -> np.ndarray:
    return np.array([[hpq(h, p, q) for q in range(n + 1)]
                     for p in range(n + 1)], dtype=float)


def main() -> None:
